 {auto* h=create(22);auto& s=*h;s.autoRestart=false;s.tick=200;s.player()[0]=770*256;s.player()[1]=250*256;for(auto& a:s.actors)if(a.spawn[1]!=60&&a.spawn[1]!=65&&a.spawn[1]!=66)a.state[40]|=1;auto it=std::find_if(s.actors.begin(),s.actors.end(),[](auto& a){return a.spawn[0]==56;});assert(it!=s.actors.end());uint32_t pixels[38400];int32_t info[8];for(int t=0;t<500;t++){assert(!s2_session_step(h,0,pixels,38400,info));assert(!(it->state[40]&1));assert(it->state[1]<285*256);}assert(it->spawnSettled);s2_session_destroy(h);}
